preToolUse.powershell:
$input = [Console]::In.ReadToEnd()
if ($input -imatch '(sudo\s+)?\brm\b\s+(-\S*r\S*f\S*|-\S*f\S*r\S*|--recursive\s+.*--force|--force\s+.*--recursive)\s+/+\*?\s*($|[;&|])') {
  Write-Output '{"permissionDecision":"ask","permissionDecisionReason":"Blocked: recursive force-delete targeting root (/) is destructive and irreversible."}'
  exit 0
}
if ($input -imatch '\b(curl|wget)\b[^|]*\|\s*(sudo\s+)?(sh|bash|zsh)\b') {
  Write-Output '{"permissionDecision":"ask","permissionDecisionReason":"Blocked: piping a remote script directly into a shell interpreter bypasses review."}'
  exit 0
}
if ($input -imatch '\bgit\s+push\s+(--force(-with-lease)?|-f)\b.*\b(origin\s+)?(main|master)\b') {
  Write-Output '{"permissionDecision":"ask","permissionDecisionReason":"Blocked: force-pushing to a protected branch (main/master) can overwrite team history."}'
  exit 0
}
if ($input -imatch '\bchmod\s+(-R\s+)?0?777\b') {
  Write-Output '{"permissionDecision":"ask","permissionDecisionReason":"Blocked: chmod 777 grants world-writable permissions, a common security misconfiguration."}'
  exit 0
}
exit 0
